import heapq


def _round(n, mode):
    return (n + 5000) // 10000 if mode == "half_up" else n // 10000


def _ledger(data, sequence_first, tax_discounted, refund_sign):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        eid = event.get("id", "anonymous:" + str(pos))
        rank = ((seq, event.get("revision", 0), pos) if sequence_first
                else (event.get("revision", 0), pos))
        if eid not in chosen or rank > chosen[eid][0]:
            chosen[eid] = (rank, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = net if tax_discounted else raw
        tax = _round(base * event.get("tax_bp", 0), mode)
        value = net + tax
        if refund_sign and event.get("kind") == "refund":
            value = -value
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + value
    return {"balances": balances}


def _component_01(data):
    return _ledger(data, True, False, True)


def _component_02(data):
    return _ledger(data, False, True, True)


