def _component_06(data):
    packages = data["packages"]
    names = list(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    choices = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name])
        choices.append([None] + versions)

    best = None
    best_vector = None
    for values in product(*choices):
        installed = {name: version for name, version in zip(names, values)
                     if version is not None}
        valid = True
        for name, (low, high) in roots.items():
            version = installed.get(name)
            if version is None or not low <= version <= high:
                valid = False
                break
        if not valid:
            continue
        for name, version in installed.items():
            if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                valid = False
                break
        if not valid:
            continue

        rows = {name: {row["version"]: row for row in packages[name]}
                for name in installed}
        edges = {}
        reachable = set()
        stack = list(roots)
        while stack and valid:
            name = stack.pop()
            if name in reachable:
                continue
            version = installed.get(name)
            if version is None:
                valid = False
                break
            reachable.add(name)
            edges[name] = []
            for dep in rows[name][version].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = installed.get(target)
                if (target_version is None or
                        not dep["min"] <= target_version <= dep["max"]):
                    valid = False
                    break
                edges[name].append(target)
                stack.append(target)
        if not valid or reachable != set(installed):
            continue

        active, finished = set(), set()
        def acyclic(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not acyclic(dep) for dep in edges.get(name, [])):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(acyclic(name) for name in reachable):
            continue

        vector = tuple(installed.get(name, -1) for name in sorted(names, reverse=True))
        if best_vector is None or vector < best_vector:
            best_vector, best = vector, installed
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    options = [job for job in jobs if job["id"] not in blocked]
    quotas = data.get("quotas", {})
    best_ids, best_value = None, None
    for selected in combinations(options, k):
        ids = tuple(sorted(job["id"] for job in selected))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(selected, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit.get(data["source"], 0)
    start_state = (data["source"], initial_mask, data["coupons"])
    start = data["start"]
    distances = {start_state: start}
    queue = [(start, data["source"], initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if (node == data["target"] and mask == full and remaining == 0
                and time <= data["deadline"]):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)),
                                remaining - 1))
            next_node = edge["v"]
            next_mask = mask | bit.get(next_node, 0)
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (next_node, next_mask, left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, left))
    return {"arrival": None}


